// ============================================================
// Cek IP egress n8n
// Tujuan: tahu IP mana yang dilihat Kirimi, untuk diajukan unblock
// ke support@kirimi.id.
//
// Dicek lewat DUA jalur, karena belum tentu sama:
//   - node HTTP Request : jalan di proses utama n8n
//   - Code node ini     : jalan lewat JsTaskRunner (n8n 2.x)
// Provider-nya sengaja sama (ipify) supaya yang dibandingkan
// murni jalur eksekusinya, bukan beda layanan.
// ============================================================

const fromHttpNode = $('IP via HTTP Request').first().json.ip || '(tidak terbaca)';

let fromCodeNode = '(gagal)';
try {
  const r = await this.helpers.httpRequest({
    url: 'https://api.ipify.org?format=json',
    json: true,
    timeout: 15000,
  });
  fromCodeNode = (r && r.ip) ? r.ip : JSON.stringify(r);
} catch (e) {
  fromCodeNode = 'ERROR: ' + (e && e.message ? e.message : String(e));
}

const sama = fromHttpNode === fromCodeNode;

return [{
  json: {
    ip_via_http_node: fromHttpNode,
    ip_via_code_node: fromCodeNode,
    kedua_jalur_sama: sama,
    langkah_berikutnya: sama
      ? 'Kirim IP ini ke support@kirimi.id untuk minta pencabutan blokir.'
      : 'Dua jalur keluar lewat IP BERBEDA. Kirim KEDUANYA ke support@kirimi.id.',
  },
}];
